SELECT 
FROM practice_subject s


    s.deleted = 0

        AND s.dept_id = #{scopeDeptId}


        AND s.dept_id = #{deptId}


        AND s.module_id = #{moduleId}


        AND s.bank_id = #{bankId}


        AND s.chapter = #{chapter}


        AND s.status = #{status}


        AND s.direction = #{direction}


        AND s.difficulty = #{difficulty}



        AND (s.title LIKE CONCAT('%', #{content}, '%')
             OR s.content LIKE CONCAT('%', #{content}, '%'))


ORDER BY s.status DESC, m.sort_no ASC, s.module_id ASC, s.sort_no ASC, s.id DESC

SELECT FROM practice_subject s
WHERE s.deleted = 0 AND s.status = 1 AND s.dept_id = #{deptId}
AND s.module_id = #{moduleId}
ORDER BY m.sort_no ASC, s.module_id ASC, s.sort_no ASC, s.id ASC
